impl Block2dDiff {
    /// 🧬️ Applies sparse document changes to the artifact.
    pub fn apply_to_artifact(&self, artifact: &Block2dArtifact) -> protocol::MutationApplyResult<Block2dArtifact> {
        Ok({
            if let Some(replacement) = &self.artifact {
                return Ok((**replacement).clone());
            }
            let mut next = artifact.clone();
            if let Some(schema) = &self.schema {
                next.schema = schema.clone();
            }
            if let Some(node_kind) = &self.node_kind {
                next.node_kind = node_kind.clone();
            }
            if let Some(presentation) = &self.presentation {
                next.presentation = presentation.clone();
            }
            if let Some(delta) = &self.handle_kinds {
                next.handle_kinds = apply_handle_kinds_delta(&next.handle_kinds, delta).map_err(|error| error.under(["handleKinds"]))?;
            }
            if let Some(delta) = &self.handles {
                next.handles = apply_handles_delta(&next.handles, delta).map_err(|error| error.under(["handles"]))?;
            }
            if let Some(delta) = &self.compatibility {
                next.compatibility = apply_compatibility_delta(&next.compatibility, delta).map_err(|error| error.under(["compatibility"]))?;
            }
            if let Some(delta) = &self.attributes {
                next.attributes = apply_attributes_delta(&next.attributes, delta).map_err(|error| error.under(["attributes"]))?;
            }
            if let Some(list) = &self.authors {
                next.authors = list.values.clone();
            }
            if let Some(camera2d) = &self.camera2d {
                next.camera2d = camera2d.clone();
            }
            if let Some(meta) = &self.meta {
                next.meta = meta.clone();
            }
            next
        })
    }
}

impl MutationDiff<Block2dSnapshot> for Block2dDiff {
    fn apply(&self, snapshot: &Block2dSnapshot) -> protocol::MutationApplyResult<Block2dSnapshot> {
        Ok({
            if let Some(replacement) = &self.artifact {
                return Ok(replacement.to_snapshot());
            }
            let mut next = snapshot.clone();
            if let Some(schema) = &self.schema {
                next.schema = schema.clone();
            }
            if let Some(node_kind) = &self.node_kind {
                next.node_kind = node_kind.clone();
            }
            if let Some(presentation) = &self.presentation {
                next.presentation = presentation.clone();
            }
            if let Some(delta) = &self.handle_kinds {
                next.handle_kinds = apply_handle_kinds_delta(&next.handle_kinds, delta).map_err(|error| error.under(["handleKinds"]))?;
            }
            if let Some(delta) = &self.handles {
                next.handles = apply_handles_delta(&next.handles, delta).map_err(|error| error.under(["handles"]))?;
            }
            if let Some(delta) = &self.compatibility {
                next.compatibility = apply_compatibility_delta(&next.compatibility, delta).map_err(|error| error.under(["compatibility"]))?;
            }
            if let Some(delta) = &self.attributes {
                next.attributes = apply_attributes_delta(&next.attributes, delta).map_err(|error| error.under(["attributes"]))?;
            }
            if let Some(list) = &self.authors {
                next.authors = list.values.clone();
            }
            if let Some(camera2d) = &self.camera2d {
                next.camera2d = camera2d.clone();
            }
            if let Some(meta) = &self.meta {
                next.meta = meta.clone();
            }
            next
        })
    }
    fn absorb(&mut self, other: Self) {
        if other.artifact.is_some() {
            *self = other;
            return;
        }
        macro_rules! take {
            ($field:ident) => {
                if other.$field.is_some() {
                    self.$field = other.$field;
                }
            };
        }
        take!(schema);
        take!(node_kind);
        take!(presentation);
        take!(authors);
        take!(camera2d);
        take!(meta);
        /// 🩹 Two edits touching the same item coalesce into ONE patch entry: `apply` refuses a
        /// collection whose `patched` list names the same id twice
        /// (`mutation.apply.duplicate-target`), so a plain `extend` breaks the diff-absorb law the
        /// moment one gesture patches the same row twice. Every patch here is a whole-item
        /// `replacement`, so the later entry simply supersedes the earlier one.
        fn absorb_patches<E>(target: &mut Vec<E>, incoming: Vec<E>, id_of: impl Fn(&E) -> &str) {
            for entry in incoming {
                match target.iter().position(|existing| id_of(existing) == id_of(&entry)) {
                    Some(position) => target[position] = entry,
                    None => target.push(entry),
                }
            }
        }
        fn absorb_delta<D, F>(target: &mut Option<D>, incoming: Option<D>, merge: F)
        where
            F: FnOnce(&mut D, D),
        {
            if let Some(src) = incoming {
                match target {
                    Some(dst) => merge(dst, src),
                    None => *target = Some(src),
                }
            }
        }
        absorb_delta(&mut self.handle_kinds, other.handle_kinds, |dst, src| {
            dst.removed.extend(src.removed);
            dst.added.extend(src.added);
            absorb_patches(&mut dst.patched, src.patched, |entry| entry.id.as_str());
            if src.reordered.is_some() {
                dst.reordered = src.reordered;
            }
        });
        absorb_delta(&mut self.handles, other.handles, |dst, src| {
            dst.removed.extend(src.removed);
            dst.added.extend(src.added);
            absorb_patches(&mut dst.patched, src.patched, |entry| entry.id.as_str());
            if src.reordered.is_some() {
                dst.reordered = src.reordered;
            }
        });
        absorb_delta(&mut self.compatibility, other.compatibility, |dst, src| {
            dst.removed.extend(src.removed);
            dst.added.extend(src.added);
            absorb_patches(&mut dst.patched, src.patched, |entry| entry.id.as_str());
            if src.reordered.is_some() {
                dst.reordered = src.reordered;
            }
        });
        absorb_delta(&mut self.attributes, other.attributes, |dst, src| {
            dst.removed.extend(src.removed);
            dst.added.extend(src.added);
            absorb_patches(&mut dst.patched, src.patched, |entry| entry.id.as_str());
            if src.reordered.is_some() {
                dst.reordered = src.reordered;
            }
        });
    }
}

