        }

fn absorb_col<D>(target: &mut Option<D>, incoming: Option<D>, merge: impl FnOnce(&mut D, D)) {
            if let Some(src) = incoming {
                match target {
                    Some(dst) => merge(dst, src),
                    None => *target = Some(src),
                }
            }
        }

